METHOD: в консоли выполнить скрипт, который на каждый клик по странице сохраняет координаты `clientX/Y` в `localStorage` (массив). После 30 секунд (или после закрытия вкладки) скрипт рисует полупрозрачный canvas‑оверлей с кругами, размер которых пропорционален количеству кликов в данной области. Пример:
```js
(() => {
const KEY = 'clickHeatmap';
const data = JSON.parse(localStorage.getItem(KEY)||'[]');
document.addEventListener('click', e => {
data.push({x:e.clientX, y:e.clientY});
localStorage.setItem(KEY, JSON.stringify(data));
});
const draw = () => {
const canvas = document.createElement('canvas');
canvas.style.position='fixed';canvas.style.top=0;canvas.style.left=0;
canvas.width=window.innerWidth;canvas.height=window.innerHeight;
canvas.style.pointerEvents='none';canvas.style.zIndex=9999;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
data.forEach(p => {
const rad = 20;
const grad = ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,rad);
grad.addColorStop(0,'rgba(255,0,0,0.4)');
grad.addColorStop(1,'rgba(255,0,0,0)');
ctx.fillStyle=grad;
ctx.beginPath();ctx.arc(p.x,p.y,rad,0,2*Math.PI);ctx.fill();
});
};
setTimeout(draw, 30000); // 30 сек
})();
```

